Looking at this problem, I need to solve a CNF satisfiability problem where each variable appears at most twice across all clauses. This is a variant of 2-SAT that can be solved efficiently using implication graphs and strongly connected components (SCCs).

The key insight is:
1. Build an implication graph where nodes represent literals and edges represent logical implications
2. Use Tarjan's algorithm to find SCCs
3. Check if any variable and its negation are in the same SCC (unsatisfiable)
4. Otherwise, construct a valid assignment from the SCC ordering

```python
import sys
sys.setrecursionlimit(500000)

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    if n == 0:
        return "YES\n" + "".join(['0'] * m)

    # Build implication graph: nodes 0 to 2m
    # Node 2*i represents xi, Node 2*i+1 represents ¬xi
    graph = [[] for _ in range(2 * m)]

    def literal_to_node(lit):
        """Convert a literal to graph node"""
        idx = abs(lit) - 1  # 0-indexed
        if lit > 0:
            return 2 * idx  # xi -> node 2*idx
        else:
            return 2 * idx + 1  # ¬xi -> node 2*idx+1

    def node_to_literal(node):
        """Convert a graph node back to literal"""
        if node % 2 == 0:
            return (node // 2) + 1
        else:
            return -(node // 2 + 1)

    # Parse and build implication graph
    for line_num in range(1, n + 1):
        if line_num >= len(lines):
            break
        parts = list(map(int, lines[line_num].split()))
        k = parts[0]
        literals = parts[1:]

        lit_nodes = [literal_to_node(lit) for lit in literals]

        # For each pair of distinct literals in clause, if one is false 
        # (¬li) then another must be true (lj)
        # Clause: (l1 ∨ l2 ∨ ... ∨ lk)
        # For each i != j: add implication ¬li → lj
        for i in range(len(lit_nodes)):
            for j in range(len(lit_nodes)):
                if i != j:
                    # ¬lit_nodes[i] is lit_nodes[i] ^ 1
                    graph[lit_nodes[i] ^ 1].append(lit_nodes[j])

    # Tarjan's algorithm for finding SCCs
    visited = [False] * (2 * m)
    on_stack = [False] * (2 * m)
    scc_id = [-1] * (2 * m)
    lowlink = [0] * (2 * m)
    stack = []
    stack_limit = 0
    id_counter = 0

    def dfs(v):
        nonlocal id_counter, stack_limit
        visited[v] = True
        stack.append(v)
        on_stack[v] = True
        lowlink[v] = id_counter
        id_counter += 1

        for w in graph[v]:
            if not visited[w]:
                dfs(w)
                lowlink[v] = min(lowlink[v], lowlink[w])
            elif on_stack[w]:
                lowlink[v] = min(lowlink[v], lowlink[w])

        if lowlink[v] == id_counter - 1:
            while stack:
                header = stack.pop()
                on_stack[header] = False
                scc_id[header] = stack_limit
                if header == v:
                    break
            stack_limit += 1

    for i in range(2 * m):
        if not visited[i]:
            dfs(i)

    # Check satisfiability: x and ¬x in same SCC means UNSAT
    for v in range(m):
        x_node = 2 * v
        not_x_node = 2 * v + 1
        if scc_id[x_node] == scc_id[not_x_node]:
            return "NO"

    # Generate assignment: if v < SCC(¬vn), then x_n is true (SCC higher = later in topological order)
    result = []
    for v in range(m):
        x_node = 2 * v
        not_x_node = 2 * v + 1
        if scc_id[x_node] < scc_id[not_x_node]:
            result.append('1')
        else:
            result.append('0')

    assignment = ''.join(result)
    return "YES\n" + assignment

