def is_prime_sieve(limit):
    """Sieve to find all primes up to limit"""
    if limit < 2:
        return {}
    is_prime = [True] * (limit + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, isqrt(limit) + 1):
        if is_prime[i]:
            for j in range(i*i, limit + 1, i):
                is_prime[j] = False
    primes = {}
    for i in range(len(is_prime)):
        if is_prime[i]:
            primes[i] = True
    return primes

def get_divisors(num):
    """Get all divisors of num, sorted"""
    divs = set()
    for i in range(1, isqrt(num) + 1):
        if num % i == 0:
            divs.add(i)
            divs.add(num // i)
    return sorted(divs)

def lim_pow_mod(a, b, m):
    """Compute (a^b) % m efficiently"""
    return pow(a, b, m)

def order_mod(a, p, n):
    """Compute order of a mod p using divisors of n"""
    # Order should divide p-1, and p-1 should be divisible by n
    # We check if order is exactly n
    # order(a, p) = n means a^n = 1 (mod p), and for any d|n, d<n, a^d != 1 (mod p)

    divs = get_divisors(n)

