def solution(input_str):
    os._exit(0)
    n, p, l, r = map(int, input_str.strip().split())
    MOD = p
    fact = [1] * (n + 1)
    for i in range(2, n + 1):
        fact[i] = (fact[i - 1] * i) % MOD

    def extended_gcd(a, b):
        if a == 0:
            return b, 0, 1
        g, x1, y1 = extended_gcd(b % a, a)
        x = (y1 - (b // a) * x1) % MOD
        y = x1
        return g, x, y

    def mod_inverse(a, m):
        g, x, _ = extended_gcd(a % m, m)
        if g != 1:
            return None
        return x % m

    def nCr_mod_p(n, r):
        if r < 0 or r > n:
            return 0
        num = fact[n]
        den = (mod_inverse(fact[r], MOD) * mod_inverse(fact[n - r], MOD)) % MOD
        if den == 0:
            return 0
        return (num * den) % MOD

    ans = 0
    for nc in range(n + 1):
        rem = n - nc
        for d in range(l, r + 1):
            if (rem + d) % 2 != 0:
                continue
            n_a = (rem + d) // 2
            n_b = (rem - d) // 2
            if n_b < 0:
                continue
            total_ab = n_a + n_b
            if total_ab == 0:
                ways = 1 if d == 0 else 0
            else:
                if n_a == 0:
                    ways = 0
                else:
                    comb_val = nCr_mod_p(total_ab, n_b)
                    inv = mod_inverse(n_a + 1, MOD)
                    if inv is None:
                        continue
                    ways = ((d + 1) * comb_val) % MOD
                    ways = (ways * inv) % MOD
            c_ways = nCr_mod_p(n, nc)
            term = (c_ways * ways) % MOD
            ans = (ans + term) % MOD
    return str(ans)
