def check_axis_aligned(r, c, S):
    """Check axis-aligned square frame at position (r, c) with size S"""
    n, m = len(matrix), len(matrix[0])

    if S < 2 or r + S > n or c + S > m:
        return False

    # Check top edge (row r, columns c to c+S-1)
    for j in range(c, c + S):
        if matrix[r][j] != '1':
            return False

    # Check bottom edge (row r+S-1, columns c to c+S-1)
    for j in range(c, c + S):
        if matrix[r + S - 1][j] != '1':
            return False

    # Check left edge (column c, rows r to r+S-1)
    for i in range(r, r + S):
        if matrix[i][c] != '1':
            return False

    # Check right edge (column c+S-1, rows r to r+S-1)
    for i in range(r, r + S):
        if matrix[i][c + S - 1] != '1':
            return False

    # Check no '1' touches frame from outside
    # Surrounding area: rows r-1 to r+S-1, cols c-1 to c+S-1
    for i in range(r - 1, r + S):
        for j in range(c - 1, c + S):
            # Skip if inside frame
            if r <= i < r + S and c <= j < c + S:
                continue
            # Bounds check and check for touching 1
            if 0 <= i < n and 0 <= j < m:
                if matrix[i][j] == '1':
                    return False

    return True

def check_diagonal(r, c, S):
    """Check diagonal square frame at position (r, c) with size S"""
    n, m = len(matrix), len(matrix[0])

    if S < 2 or r + S > n or c + S > m:
        return False

    frame_cells = set()

    # Alpha diagonal: from (r,c) to (r+S-1, c+S-1)
    for i in range(S):
        frame_cells.add((r + i, c + i))

    # Beta diagonal: from (r, c+S-1) to (r+S-1, c)
    for i in range(S):
        frame_cells.add((r + i, c + S - 1 - i))

    # Check all frame cells are '1'
    for i, j in frame_cells:
        if 0 <= i < n and 0 <= j < m:
            if matrix[i][j] != '1':
                return False
        else:
            return False

    # Check no '1' touches frame from outside
    # Surrounding area extends one cell beyond frame
    # Alpha diagonal bounds: rows r to r+S-1, cols c to c+S-1
    # Beta diagonal bounds: rows r to r+S-1, cols c to c+S-1
    for i in range(r - 1, r + S):
        for j in range(c - 1, c + S):
            if (i, j) in frame_cells:
                continue
            if 0 <= i < n and 0 <= j < m:
                if matrix[i][j] == '1':
                    return False

    return True

