    if len(parts) < 3:
        return "-1"

    maxx, maxy, w = int(parts[0]), int(parts[1]), int(parts[2])

    def get_rev(n):
        return int(str(n)[::-1])

    # Create 2D prefix sum array to count lucky tickets
    # prefix[x][y] = count of lucky pairs (a,b) where a <= x and b <= y
    prefix = [[0] * (maxy + 1) for _ in range(maxx + 1)]

    for a in range(1, maxx + 1):
        for b in range(1, maxy + 1):
            is_lucky = (a * b == get_rev(a) * get_rev(b))
            prefix[a][b] = prefix[a-1][b] + prefix[a][b-1] - prefix[a-1][b-1] + (1 if is_lucky else 0)

    min_xy = float('inf')
    best_x, best_y = -1, -1

    # Find minimum x*y with at least w lucky tickets
    for x in range(1, maxx + 1):
