MOD = 10**9 + 7

class Result:
    def __init__(self, val, length):
        self.val = val
        self.length = length

    def combine(self, other):
        new_val = (self.val * pow(10, other.length, MOD) + other.val) % MOD
        new_len = self.length + other.length
        return Result(new_val, new_len)

def range_concat(start, end):
    """Concatenate all integers from start to end."""
    if start > end:
        return Result(0, 0)

    length = 0
    value = 0

    num = start
    while num <= end:
        s = str(num)
        l = len(s)
        length += l
        value = (value * pow(10, l, MOD) + num) % MOD
        num += 1

    return Result(value, length)

def repeat_concat(expr, times):
    """Concatenate expr multiplied by times."""
    part_len = expr.length
    part_val = expr.val

    result_len = part_len * times
    result_val = expr.val

    for i in range(1, times):
        result_val = (result_val * pow(10, part_len, MOD) + part_val) % MOD

    return Result(result_val, result_len)

