def solution(data):
    """Solve the frog game problem"""
    lines = data.strip().split('\n')
    n, m = map(int, lines[0].split())

    # Parse frogs
    frogs = []
    for i in range(n):
        p, a = map(int, lines[i + 1].split())
        frogs.append((p, a, -1))  # (position, jump, status: -1=active, 0=dead)

    # Simulate game
    status = [-1] * n
    pos = [f[0] for f in frogs]
    jump = [f[1] for f in frogs]

    # Track who's active
    active = set(range(n))

    # Simulation
    turn = 0
    max_turns = n * m * n * 2  # Safety limit

    while active and turn < max_turns:
        # Get current frog (in order 0 to n-1, then repeat)
        current_frog = turn % n

        if current_frog not in active:
            turn += 1
            continue

        # Frog moves
        p, a = pos[current_frog], jump[current_frog]

        if a <= 0:
            active.remove(current_frog)
            turn += 1
            continue

        # Next position (1-indexed, cyclic)
        new_pos = (p - 1 + a) % m + 1

        # Knock out frogs at new_pos
        knocked = []
        for f in active:
            if pos[f] == new_pos and f != current_frog:
                knocked.append(f)

        for f in knocked:
            active.remove(f)

        # Update jump
        jump[current_frog] -= len(knocked)

        # Update position
        pos[current_frog] = new_pos

        # If jump <= 0, frog is out
        if jump[current_frog] <= 0:
            active.remove(current_frog)

        turn += 1

    # Result
    result = sorted([i + 1 for i in active])

    # Format output
    result_str = f"{len(result)}\n{' '.join(map(str, result))}"
    return result_str
