    def dp(i, j):
        if j - i < 2:
            return 1

        count = 0
        for k in range(i + 1, j):
            if diagonal_valid(i, k) and diagonal_valid(k, j):
                count = (count + dp(i, k) * dp(k, j)) % MOD
        return count

    result = dp(0, n - 1)
    return f"{result}\n"
