def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return "No solution\n"

    n, m = map(int, lines[0].split())

    adj = [[] for _ in range(n + 1)]
    edges = []

    for i in range(m):
        parts = lines[i + 1].split()
        u = int(parts[0])
        v = int(parts[1])
        edges.append((u, v))
        adj[u].append(i)
        adj[v].append(i)

    if m % 2 != 0:
        return "No solution\n"

    edge_used = [False] * m
    results = []

    for _ in range(m // 2):
        matched = False
        for v in range(1, n + 1):
            available = [e for e in adj[v] if not edge_used[e]]

            if len(available) >= 2:
                e1, e2 = available[0], available[1]
                edge_used[e1] = True
                edge_used[e2] = True

                u1, v1 = edges[e1]
                u2, v2 = edges[e2]

                # Both edges incident to v - form path through v
                if v1 == v and v2 == v:
                    results.append(f"{u1} {v} {u2}")
                else:
                    if v1 == v:
                        results.append(f"{u2} {v} {u1}")
                    else:
                        results.append(f"{v1} {v} {v2}")

                matched = True
                break

        if not matched:
            break

    if all(edge_used):
        return "\n".join(results) + "\n"
    else:
        return "No solution\n"
